mapper.select:
SELECT id, event_type, recipient_id, actor_id, resource_id, summary, attempts, created_at
FROM outbox_event WHERE status = 'IN_FLIGHT' AND claim_token = #{token}
ORDER BY created_at, id

mapper.update:
UPDATE outbox_event
SET status = CASE WHEN #{dead} THEN 'DEAD' ELSE 'RETRY' END,
    claim_token = NULL, lease_until = NULL,
    next_attempt_at = DATE_ADD(CURRENT_TIMESTAMP(6), INTERVAL #{backoffSeconds} SECOND),
    last_error = #{error}
WHERE id = #{id} AND status = 'IN_FLIGHT' AND claim_token = #{token}
